"""Dump the auto-generated Metal kernel for the walker (Model._metal_source)."""
import os, macgym as mg
OUT = os.path.join(os.path.dirname(__file__), "../../web/deck/data")
robot, task = mg.robots.walker()
hdr, src = robot.build_model()._metal_source()
text = "// auto-generated by macgym Model._metal_source() for mg.robots.walker()\n// ---- header (per-robot constants)\n" + hdr + "\n// ---- kernel body (one thread per env)\n" + src
open(os.path.join(OUT, "walker_kernel.metal"), "w").write(text)
print("lines", len(text.splitlines()), "header lines", len(hdr.splitlines()), "body lines", len(src.splitlines()))
